  const results = ms.search({
    queries: [
      { queries: ['del'], filter: (r) => { filterCalls++; return r.category === 'poetry' } },
      { queries: ['como'], filter: (r) => { filterCalls++; return r.category === 'fiction' } }
    ]
  })
  expect(results.length).toBe(2)
